namespace v2rayN.Desktop;

/// <summary>Translations of the V2pn-only strings in <see cref="L"/>, keyed by the English text.</summary>
internal static class LTranslations
{
    // Returns null when there is no translation, so the caller falls back to English.
    public static string? Get(CultureInfo culture, string en)
    {
        for (var c = culture; !string.IsNullOrEmpty(c.Name); c = c.Parent)
        {
            if (Table.TryGetValue(c.Name, out var map) && map.TryGetValue(en, out var text))
            {
                return text;
            }
        }
        return null;
    }

